MM.area({
  id:'professores', layout:'perfis',
  botoes:[{rotulo:{pt:'Baixar todas as fotos (.zip)', es:'Descargar todas las fotos (.zip)'}, url:'../assets/fotos/professores/fotos-professores.zip', baixar:true}],
  filtros:[{campo:'categoria', rotulo:{pt:'Papel', es:'Rol'}}, {campo:'area', rotulo:{pt:'Especialidade', es:'Especialidad'}, ordem:'alfa'}],
  gerar: function(CAT){
    var norm = MM.norm, PREENCHER = {pt:'a preencher', es:'por completar'};
    return PROFESSORES.map(function(p){
      var n = (CAT.items || []).filter(function(v){ return norm((v.p || '') + ' ' + (v.qa || '')).indexOf(p.chave) >= 0; });
      var ig = String(p.instagram || '').trim().replace(/^@/, '').replace(/^https?:\/\/(www\.)?instagram\.com\//, '').replace(/\/.*$/, '');
      var tel = String(p.telefone || '').trim(), digitos = tel.replace(/\D/g, '');
      var links = [];
      if (ig) links.push({rotulo:'Instagram', url:'https://instagram.com/' + ig});
      if (digitos) links.push({rotulo:'WhatsApp', url:'https://wa.me/' + digitos});
      if (p.fotoAlta) links.push({rotulo:{pt:'Baixar foto (' + (p.fotoAlta === 'png' ? 'PNG sem fundo' : 'JPG') + ')', es:'Descargar foto (' + (p.fotoAlta === 'png' ? 'PNG sin fondo' : 'JPG') + ')'}, url:'../assets/fotos/professores/alta/' + p.id + '.' + p.fotoAlta, baixar:true});
      var bio = p.bio;
      if (bio && p.bioOriginal === 'es') bio = {pt:'Formação (texto original da apresentação, em espanhol):\n\n' + p.bio.es, es:p.bio.es};
      return {
        id: p.id, titulo: p.nome,
        foto: p.foto ? '../assets/fotos/professores/' + p.id + '.jpg' : null,
        categoria: p.cargo ? {pt:'Direção', es:'Dirección'} : p.coord ? {pt:'Coordenador(a)', es:'Coordinador(a)'} : {pt:'Professor(a)', es:'Profesor(a)'},
        area: p.especialidade || null,
        especialidade: p.cargo || p.especialidade,
        contato: [ig ? '@' + ig : null, tel || null].filter(Boolean).join(' · '),
        texto: bio || null,
        resumo: p.cursos.length ? p.cursos.slice(0,2).join(' · ') + (p.cursos.length > 2 ? ' +' + (p.cursos.length - 2) : '')
              : (p.leciona && p.leciona.length ? {pt:'Professor(a) em ' + p.leciona.length + (p.leciona.length > 1 ? ' cursos' : ' curso'), es:'Profesor(a) en ' + p.leciona.length + (p.leciona.length > 1 ? ' cursos' : ' curso')} : null),
        status: (ig && p.especialidade) ? null : 'preencher',
        campos: [
          {rotulo:{pt:'Nome completo', es:'Nombre completo'}, valor: p.nomeCompleto || ''},
          {rotulo:{pt:'Especialidade', es:'Especialidad'}, valor: p.cargo || p.especialidade || PREENCHER},
          {rotulo:'Instagram', valor: ig ? '@' + ig : PREENCHER},
          {rotulo:{pt:'Telefone', es:'Teléfono'}, valor: tel || PREENCHER},
          {rotulo:{pt:'Coordena', es:'Coordina'}, valor: p.cursos.join(', ')},
          {rotulo:{pt:'Dá aula em', es:'Enseña en'}, valor: (p.leciona || []).join(', ')}
        ],
        links: links,
        videos: n.length ? {q: p.chave, rotulo:{pt:'Ver vídeos na Videoteca', es:'Ver videos en la Videoteca'}} : null
      };
    });
  }
});
